let legacyBrowserState=null; try{legacyBrowserState=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(LEGACY_KEY)||'null')}catch(e){}
let d=legacyBrowserState||seed;
let cloudMode=false, cloudAuthenticated=false, cloudVersion=null, cloudSavePromise=Promise.resolve(), cloudHydrating=false;
async function api(url,options={}){const o={credentials:'include',...options,headers:{...(options.headers||{})}};if(o.body&&typeof o.body!=='string'){o.headers['Content-Type']='application/json';o.body=JSON.stringify(o.body)}const r=await fetch(url,o);let data=null;try{data=await r.json()}catch{}if(!r.ok)throw new Error(data?.error||`Request failed (${r.status})`);if(data&&Number.isInteger(Number(data.version))&&cloudAuthenticated)cloudVersion=Number(data.version);return data}
async function financeMutation(action,payload){if(!cloudMode||!cloudAuthenticated)throw new Error('Cloud database login is required for financial changes.');return api('/api/finance-mutation',{method:'POST',body:{action,...payload}})}
async function loadPublicCloud(){try{const x=await api('/api/public-bootstrap');if(x?.settings){d={...d,...x};d.notices=x.notices||d.notices;d.settings={...d.settings,...x.settings};d.courses=x.courses||d.courses;d.batches=x.batches||d.batches;cloudMode=true;normalize();return true}}catch(e){}return false}
async function loadPrivateCloud(){
  const x=await api('/api/bootstrap');

  if(!x || !x.state){
    throw new Error('Cloud data could not be loaded.');
  }

  d=x.state;

  if(x.user){
    currentUser=x.user;

    if(x.user.role){
      role=x.user.role;
    }
  }

  cloudVersion=Number(x.version||1);
  cloudMode=true;
  cloudAuthenticated=true;
  cloudHydrating=true;

  normalize();

  cloudHydrating=false;

  return true;
}
function queueCloudSave(){if(cloudHydrating||!cloudMode||!cloudAuthenticated||!currentUser||cloudVersion==null)return;const payload=JSON.parse(JSON.stringify(d));const expectedVersion=cloudVersion;cloudSavePromise=cloudSavePromise.then(async()=>{const out=await api('/api/state',{method:'POST',body:{state:payload,version:expectedVersion}});cloudVersion=Number(out.version||expectedVersion+1);}).catch(e=>{console.error(e); if(String(e.message||'').includes('DATA_CONFLICT')){cloudAuthenticated=false; alert('এই data অন্য একটি device থেকে পরিবর্তন হয়েছে। Page reload করে আবার কাজ করুন।');}});}

function today(){return new Date().toISOString().slice(0,10)}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function audit(action,details=''){if(!d.auditLog)d.auditLog=[];d.auditLog.push({id:Date.now()+Math.random(),user:currentUser?.name||'System',userId:currentUser?.id||'',role:role||'',action,details,date:new Date().toISOString()});if(d.auditLog.length>2000)d.auditLog=d.auditLog.slice(-2000);localStorage.setItem(KEY,JSON.stringify(d))}
function auditChange(action,recordType,recordId,field,oldValue,newValue,extra=''){const fmt=v=>v===undefined||v===null||v===''?'—':String(v);const detail=`${field}: ${fmt(oldValue)} → ${fmt(newValue)}${extra?` · ${extra}`:''}`;if(!d.auditLog)d.auditLog=[];d.auditLog.push({id:Date.now()+Math.random(),user:currentUser?.name||'System',userId:currentUser?.id||'',role:role||'',action,recordType,recordId,field,oldValue:fmt(oldValue),newValue:fmt(newValue),details:detail,date:new Date().toISOString()});if(d.auditLog.length>2000)d.auditLog=d.auditLog.slice(-2000);localStorage.setItem(KEY,JSON.stringify(d))}
function auditWrap(name,action){const fn=window[name];if(typeof fn!=='function'||fn.__auditWrapped)return;const w=function(...args){const before=Date.now();const r=fn.apply(this,args);if(currentUser) audit(action, 'Action completed');return r};w.__auditWrapped=true;window[name]=w}
function saveLocalCache(){
  const cache=JSON.parse(JSON.stringify(d));
  delete cache.settings?.adminPassword;
  (cache.teachers||[]).forEach(t=>delete t.password);
  (cache.students||[]).forEach(s=>delete s.password);
  if(cache.settings?.drive){delete cache.settings.drive.apiKey;delete cache.settings.drive.endpoint;}
  localStorage.setItem(KEY,JSON.stringify(cache));
}
function save(){
  saveLocalCache();
  queueCloudSave();
}
function notificationItems(){
  const out=[], now=today();
  const add=(type,title,text,key,priority='normal')=>out.push({type,title,text,key,priority});
  const visibleStudents=role==='trainer'?trainerStudents():d.students;
  visibleStudents.forEach(s=>{
    const due=Math.max(0,(+s.fee||0)-(+s.paid||0));
    if(due>0)add('Payment Due','Payment Due',`${s.name} (${s.id}) — ${money(due)} due`,`payment:${s.id}`,due>0?'high':'normal');
    if(s.nextPaymentDate&&daysUntil(s.nextPaymentDate)>=0&&daysUntil(s.nextPaymentDate)<=7)add('Payment Reminder','Payment Reminder',`${s.name} — next payment ${s.nextPaymentDate}`,`nextpay:${s.id}`);
  });
  d.batches.forEach(b=>{
    const meta=d.settings.batchMeta?.[b]||{}, start=meta.startDate, dur=+(meta.durationMonths||6);
    if(start){
      const end=new Date(start+'T00:00:00'); end.setMonth(end.getMonth()+dur);
      const days=Math.ceil((end-new Date(now+'T00:00:00'))/86400000);
      if(days>=0&&days<=30)add('Batch Ending','Batch Ending Reminder',`${b} — training ends in ${days} day${days===1?'':'s'}`,`batchend:${b}`);
    }
  });
  d.attendance.filter(a=>a.date===now&&a.status==='Absent').forEach(a=>{
    const s=d.students.find(x=>x.id===a.student||x.id===a.studentId);
    add('Student Absent','Student Absent',`${s?.name||a.student||a.studentId||'Student'} — absent today`,`absent:${a.id||a.student||Math.random()}`,'high');
  });
  (d.exams||[]).forEach((e,i)=>{
    const ed=e.date||e.examDate||e.scheduledDate;
    const status=String(e.status||'').toLowerCase();
    if((!status||['pending','upcoming','scheduled','draft'].includes(status))&&ed&&daysUntil(ed)>=0&&daysUntil(ed)<=14)
      add('Exam Pending','Exam Pending',`${e.name||e.title||'Exam'} — ${ed}`,`exam:${e.id||i}`);
  });
  (d.certificates||[]).forEach((c,i)=>{
    const st=String(c.status||'').toLowerCase();
    if(!['completed','issued','delivered'].includes(st))add('Certificate Pending','Certificate Pending',`${c.name||c.studentName||c.id||'Certificate'} — pending`,`cert:${c.id||i}`);
  });
  (d.staffSalaries||[]).forEach((s,i)=>{
    if(String(s.status||'').toLowerCase()==='pending'||s.paid===false)add('Salary Reminder','Salary/Payment Reminder',`${s.name||s.staffName||s.staff||'Staff'} — salary/payment pending`,`salary:${s.id||i}`,'high');
  });
  return out;
}
function notificationUnreadCount(){return notificationItems().filter(n=>!d.notificationState?.[n.key]).length}
function markAllNotificationsRead(){if(!d.notificationState)d.notificationState={};notificationItems().forEach(n=>d.notificationState[n.key]=true);save();render('notifications')}
function markNotificationRead(key){if(!d.notificationState)d.notificationState={};d.notificationState[key]=true;save();render('notifications')}

function money(n){return '৳ '+(+n||0).toLocaleString('en-BD')}
function logoUrl(){return d.settings?.institutionLogo||new URL('mjptti-logo.png',location.href).href}
function letterheadUrl(){return new URL('mjptti-letterhead.jpg',location.href).href}
function addMonths(date,months=1){const x=new Date(date+'T00:00:00');x.setMonth(x.getMonth()+months);return x.toISOString().slice(0,10)}
function daysUntil(date){if(!date)return 99999;return Math.ceil((new Date(date+'T00:00:00')-new Date(today()+'T00:00:00'))/86400000)}
function normalize(){d.notificationState=d.notificationState||{};for(const k of ['auditLog','students','staff','payments','expenses','officeAdvances','staffSalaries','salarySheets','attendance','staffAttendance','exams','examList','certificates','courses','batches','teachers','notices'])if(!Array.isArray(d[k]))d[k]=[];for(const c of ['JLPT N5 & N4 Combined','JLPT N5','JLPT N4'])if(!d.courses.includes(c))d.courses.unshift(c);if(!d.settings)d.settings=seed.settings;d.settings.adminUsername=d.settings.adminUsername||'admin';d.settings.adminPassword=d.settings.adminPassword||'';d.settings.institutionName=d.settings.institutionName||d.settings.name||'Meherun JP Technical Training Institute';d.settings.institutionLogo=d.settings.institutionLogo||'';d.settings.institutionAddress=d.settings.institutionAddress||d.settings.bdAddress||'';d.settings.institutionPhone=d.settings.institutionPhone||d.settings.phone||'';d.settings.institutionEmail=d.settings.institutionEmail||d.settings.email||'';d.settings.website=d.settings.website||'';d.settings.authorizedPerson=d.settings.authorizedPerson||'';d.settings.signature=d.settings.signature||'';d.settings.seal=d.settings.seal||'';d.settings.motto=d.settings.motto||'Empowering Skills, Building Future';d.settings.certificateTitle=d.settings.certificateTitle||'CERTIFICATE OF COMPLETION';d.settings.certificateJapaneseTitle=d.settings.certificateJapaneseTitle||'技能修了証明書';d.settings.idCardTitle=d.settings.idCardTitle||'STUDENT ID CARD';d.settings.idCardFooter=d.settings.idCardFooter||'PROPERTY OF MJPTTI • PLEASE RETURN IF FOUND';d.settings.letterheadMotto=d.settings.letterheadMotto||String(d.settings.motto||'EMPOWERING SKILLS, BUILDING FUTURE');d.settings.name=d.settings.institutionName;d.settings.bdAddress=d.settings.institutionAddress;d.settings.phone=d.settings.institutionPhone;d.settings.email=d.settings.institutionEmail;d.settings.courseMeta=d.settings.courseMeta||{};d.courses=[...new Set(d.courses.map(x=>String(x).trim()).filter(Boolean))];d.courses.forEach(c=>{if(!d.settings.courseMeta[c])d.settings.courseMeta[c]={status:'Active',createdAt:today()}});d.teachers.forEach(t=>{t.courses=Array.isArray(t.courses)?t.courses.filter(c=>d.courses.includes(c)):(t.course?[t.course]:[]);t.course=t.courses[0]||t.course||''});d.settings.drive=d.settings.drive||{endpoint:'',apiKey:'',rootFolder:'MJPTTI Records',institutionalEmail:d.settings.email||''};d.settings.batchSessions=d.settings.batchSessions||{};d.settings.batchMeta=d.settings.batchMeta||{};for(const b of seed.batches){if(!d.batches.includes(b))d.batches.push(b);if(!d.settings.batchMeta[b])d.settings.batchMeta[b]={status:b==='Batch 12'?'Admission Open':'Training',startDate:'',durationMonths:6};if(!d.settings.batchSessions[b])d.settings.batchSessions[b]='Morning'}d.batches.forEach(b=>{if(!d.settings.batchMeta[b])d.settings.batchMeta[b]={status:'Upcoming',startDate:'',durationMonths:6};if(!d.settings.batchMeta[b].durationMonths)d.settings.batchMeta[b].durationMonths=6;if(!d.settings.batchSessions[b])d.settings.batchSessions[b]='Morning'});d.staff.forEach(s=>{s.category=s.category||staffCategoryFromId(s.id);s.name=s.name||'';s.designation=s.designation||'';s.phone=s.phone||'';s.email=s.email||'';s.dob=s.dob||'';s.joiningDate=s.joiningDate||'';s.bloodGroup=s.bloodGroup||'';s.nid=s.nid||'';s.address=s.address||'';s.emergencyContact=s.emergencyContact||'';s.status=s.status||'Active';s.photo=s.photo||''});d.students.forEach(s=>{s.username=s.username||s.id||nextUsername();if(!cloudMode)s.password=s.password||easyStudentPassword(s);s.batchCode=s.batchCode||batchCode(s.batch);s.fee=+s.fee||0;s.paid=+s.paid||0;s.nextPaymentDate=s.nextPaymentDate||'';s.profileUpdated=s.profileUpdated||today();s.rating=s.rating||{behavior:0,attendance:0,study:0,result:0};s.session=s.session||d.settings.batchSessions[s.batch]||'Morning'});d.payments.forEach((p,i)=>{p.receipt=p.receipt||p.receiptNumber||('REC-'+Date.now()+'-'+i);p.receiptNumber=p.receiptNumber||p.receipt;p.installment=Number(p.installment||p.installmentNo||1);p.amount=Number(p.amount||0);p.date=p.date||today();p.method=p.method||'Cash';p.reference=p.reference||'';p.note=p.note||'';p.nextDue=p.nextDue||'';p.createdAt=p.createdAt||new Date().toISOString()});if(!cloudMode&&!d.settings.easyStudentPasswordsV2){d.students.forEach(s=>s.password=easyStudentPassword(s));d.settings.easyStudentPasswordsV2=true;save()}if(!d.examList.length){const names=[...new Set(d.exams.map(x=>x.exam).filter(Boolean))];d.examList=names.map((name,i)=>({id:'EX-'+String(i+1).padStart(3,'0'),name,date:today(),total:100,batch:''}))}const byName={};d.examList.forEach(x=>byName[x.name]=x);d.exams.forEach(x=>{if(!x.examId&&byName[x.exam])x.examId=byName[x.exam].id;x.obtained=Number(x.obtained)||0;x.total=Number(x.total)||Number(byName[x.exam]?.total)||100;x.percentage=Number.isFinite(Number(x.percentage))?Number(x.percentage):x.total?+(x.obtained/x.total*100).toFixed(2):0;x.grade=x.grade||gradeOf(x.percentage);x.passMark=Number(x.passMark||byName[x.exam]?.passMark||Math.ceil((Number(x.total)||100)*.33));x.status=x.status||(Number(x.obtained)>=x.passMark?'PASS':'FAIL');x.note=x.note||''});d.examList.forEach(x=>{x.passMark=Number(x.passMark||Math.ceil((Number(x.total)||100)*.33));x.studentIds=Array.isArray(x.studentIds)?x.studentIds:[]});saveLocalCache()}
normalize();
function batchCode(batch){const i=d.batches.indexOf(batch)+1;return 'B'+String(i>0?i:99).padStart(2,'0')}
function nextStudentId(batch){const code=batchCode(batch),yy=String(new Date().getFullYear()).slice(-2);let max=0;d.students.filter(s=>s.batchCode===code||s.batch===batch).forEach(s=>{const m=String(s.id||'').match(/-(\d{3})$/);if(m)max=Math.max(max,+m[1])});return `MJPTTI-${yy}${code}-${String(max+1).padStart(3,'0')}`}
function nextUsername(){let n=d.students.reduce((m,s)=>{const x=String(s.username||'').match(/(\d{4})$/);return x?Math.max(m,+x[1]):m},0)+1;let u=`MJPTTI${String(new Date().getFullYear()).slice(-2)}${String(n).padStart(4,'0')}`;while(d.students.some(s=>s.username===u)){n++;u=`MJPTTI${String(new Date().getFullYear()).slice(-2)}${String(n).padStart(4,'0')}`}return u}
function easyStudentPassword(s){const m=String(s?.id||'').match(/(\d{3})$/);return `MJ${m?m[1]:'001'}`}
function generatePassword(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';let out='MJ-';for(let i=0;i<8;i++)out+=chars[Math.floor(Math.random()*chars.length)];return out}
async function migrateLegacyBrowserData(){
  if(!cloudMode||role!=='admin'||!legacyBrowserState)return alert('এই browser-এ পুরনো local data পাওয়া যায়নি।');
  if(!confirm('এই browser-এর পুরনো MJPTTI data Cloud database-এ upload করা হবে। Cloud-এ থাকা current data replace হবে। Continue?'))return;
  try{if(cloudVersion==null)await loadPrivateCloud();await api('/api/state',{method:'POST',body:{state:legacyBrowserState,version:cloudVersion,migration:true}});await loadPrivateCloud();alert('পুরনো browser data Cloud database-এ migrate হয়েছে।');render('dashboard');}catch(e){alert('Migration failed: '+e.message)}
}
function showPublic(){$('publicNotice').classList.remove('hide');$('login').classList.add('hide');$('app').classList.add('hide');renderPublic()}
function showLogin(){$('publicNotice').classList.add('hide');$('login').classList.remove('hide');$('app').classList.add('hide');selectRole(role)}
function selectRole(r){role=r;document.querySelectorAll('.role-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.role===r));$('u').value='';$('p').value='';$('loginHint').textContent=r==='admin'?`Manager / Super Admin: ${d.settings.adminUsername}`:r==='trainer'?'Trainer: use your Trainer ID + password':'Student: use your Username + password.'}
async function login(){const u=$('u').value.trim(),p=$('p').value;if(!cloudMode)return alert('Cloud database is not available. Configure Cloudflare D1 and Functions before portal login.');try{const x=await api('/api/auth-login',{method:'POST',body:{role,username:u,password:p}});currentUser=x.user;cloudAuthenticated=true;await loadPrivateCloud();enterApp();return}catch(e){return alert(e.message)}}
function persistSession(){/* Production authentication is server-side via HttpOnly cookie. */}
async function restoreSession(){try{const x=await api('/api/auth-me');role=x.user.role;currentUser=x.user;cloudAuthenticated=true;cloudMode=true;await loadPrivateCloud();enterApp();return true}catch(e){currentUser=null;cloudAuthenticated=false;return false}}
function enterApp(){$('login').classList.add('hide');$('publicNotice').classList.add('hide');$('app').classList.remove('hide');buildNav();applyInstitutionBranding();render(role==='student'?'studentHome':role==='trainer'?'trainerHome':'dashboard')}
async function logout(){if(cloudMode){try{await api('/api/auth-logout',{method:'POST'})}catch(e){}}cloudAuthenticated=false;currentUser=null;localStorage.removeItem('mjptti_session');showPublic()}
