async function readStudentPhoto(input){
  const file=input?.files?.[0];
  if(!file)return;
  if(file.size>5*1024*1024)return alert('Photo size must be 5 MB or less.');
  const preview=await new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=()=>reject(new Error('Unable to read photo.'));
    reader.onload=()=>{
      const img=new Image();
      img.onerror=()=>reject(new Error('Invalid image file.'));
      img.onload=()=>{
        const maxW=600,maxH=750,scale=Math.min(1,maxW/img.width,maxH/img.height);
        const canvas=document.createElement('canvas');
        canvas.width=Math.max(1,Math.round(img.width*scale)); canvas.height=Math.max(1,Math.round(img.height*scale));
        const ctx=canvas.getContext('2d'); ctx.drawImage(img,0,0,canvas.width,canvas.height);
        resolve(canvas.toDataURL('image/jpeg',.82));
      }; img.src=reader.result;
    }; reader.readAsDataURL(file);
  }).catch(e=>{alert(e.message);return null});
  if(!preview)return;
  const box=$('studentPhotoPreview'); if(box)box.innerHTML=`<img src="${esc(preview)}" alt="Student Photo">`;
  window.__mjpttiStudentPhoto=preview;
  if(cloudMode&&cloudAuthenticated){
    const studentId=String(val('editId')||'PENDING-'+Date.now());
    window.__mjpttiStudentPhotoPromise=(async()=>{
      const blob=await (await fetch(preview)).blob();
      const fd=new FormData(); fd.append('photo',blob,`${studentId}.jpg`); fd.append('studentId',studentId);
      const out=await api('/api/photo-upload',{method:'POST',body:fd});
      window.__mjpttiStudentPhoto=out.url; return out.url;
    })().catch(e=>{console.warn(e);return preview});
  }
}
