function receiveStudentOptions(){
  const batch=val('receiveBatch'), course=val('receiveCourse'), sel=$('receiveStudent');
  if(!sel)return;
  let rows=d.students.slice();
  if(batch)rows=rows.filter(s=>String(s.batch||'')===batch);
  if(course)rows=rows.filter(s=>String(s.course||'')===course);
  sel.innerHTML='<option value="">Select Student…</option>'+rows.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} — ${esc(s.id)}</option>`).join('');
  $('receiveStudentSummary').innerHTML='Student নির্বাচন করুন.';
  $('receivePaymentHistory').innerHTML='<div class="empty">Student নির্বাচন করলে payment history এখানে দেখা যাবে।</div>';
  sel.onchange=showReceiveStudent;
}
function showReceiveStudent(){
  const id=val('receiveStudent'),s=d.students.find(x=>x.id===id),box=$('receiveStudentSummary'),hist=$('receivePaymentHistory');
  if(!s){if(box)box.innerHTML='Student নির্বাচন করুন।';if(hist)hist.innerHTML='<div class="empty">Student নির্বাচন করলে payment history এখানে দেখা যাবে।</div>';return;}
  const payments=d.payments.filter(p=>p.student===s.id).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
  const totalPaid=payments.reduce((a,p)=>a+Number(p.amount||0),0);
  const due=Math.max(0,Number(s.fee||0)-Number(s.paid||0));
  const nextInstallment=payments.length?Math.max(...payments.map(p=>Number(p.installment||1)))+1:1;
  if($('receiveInstallment'))$('receiveInstallment').value=nextInstallment;
  if($('receiveAmount'))$('receiveAmount').max=due;
  if($('receiveNextDue') && s.nextPaymentDate)$('receiveNextDue').value=s.nextPaymentDate;
  box.innerHTML=`<div class="cards receive-cards">${stat('Student',esc(s.name))}${stat('Total Course Fee',money(s.fee))}${stat('Total Paid',money(s.paid))}${stat('Current Due',money(due))}</div><div class="receive-student-meta"><b>${esc(s.id)}</b> · ${esc(s.course||'')} · ${esc(s.batch||'')} ${due>0?`· <span class="pill warn">Due ${money(due)}</span>`:'· <span class="pill">Paid in Full</span>'}</div>`;
  hist.innerHTML=payments.length?`<div style="overflow:auto"><table class="table payment-history-table"><tr><th>Installment</th><th>Receipt No.</th><th>Payment Date</th><th>Method</th><th>Amount</th><th>Next Due</th><th>Action</th></tr>${payments.slice().reverse().map(p=>`<tr><td>${esc(p.installment||1)}</td><td><b>${esc(p.receipt||p.receiptNumber)}</b></td><td>${esc(p.date)}</td><td>${esc(p.method||'Cash')}</td><td>${money(p.amount)}</td><td>${esc(p.nextDue||'—')}</td><td><button class="btn" onclick="paymentReceipt('${esc(p.receipt)}')">Receipt / PDF</button></td></tr>`).join('')}</table></div><div class="payment-history-actions no-print"><button class="btn" onclick="studentStatement('${s.id}')">🧾 Print Full Payment Statement</button>${due>0?`<button class="btn" onclick="whatsappReminder('${s.id}')">💬 Send Due Reminder WhatsApp</button>`:''}</div>`:'<div class="empty">No previous payment records.</div>';
}
function openStudentPayment(id){
  if(role==='trainer')return alert('Access Denied — Payment management is available only to Manager / Super Admin.');
  render('receivePayment');
  setTimeout(()=>{
    const s=d.students.find(x=>x.id===id);if(!s)return;
    if($('receiveBatch'))$('receiveBatch').value=s.batch||'';
    if($('receiveCourse'))$('receiveCourse').value=s.course||'';
    receiveStudentOptions();
    if($('receiveStudent')){$('receiveStudent').value=s.id;showReceiveStudent();}
  },0);
}
async function saveReceivePayment(){const id=val('receiveStudent'),s=d.students.find(x=>x.id===id);if(!s)return alert('Please select a student.');const due=Math.max(0,Number(s.fee||0)-Number(s.paid||0)),amount=Number(val('receiveAmount')||0);if(!amount||amount<=0)return alert('Payment amount must be greater than 0.');if(due<=0)return alert('This student has no outstanding due.');if(amount>due)return alert(`Payment cannot exceed current due of ${money(due)}.`);const date=val('receiveDate')||today(),method=val('receiveMethod')||'Cash',reference=val('receiveReference')||'',note=val('receiveNote')||'',existing=d.payments.filter(p=>p.student===s.id).map(p=>Number(p.installment||1)),installment=Number(val('receiveInstallment')||0)||((existing.length?Math.max(...existing):0)+1),nextDue=val('receiveNextDue')||addMonths(date,1);if(cloudMode){try{const x=await api('/api/payment-receive',{method:'POST',body:{studentId:id,amount,date,method,reference,note,installment,nextDue}});d=x.state;cloudVersion=Number(x.version||cloudVersion+1);normalize();paymentReceipt(x.payment.receipt);notifyPaymentWhatsApp(d.students.find(z=>z.id===id)||s,amount);notifyManagingDirector(d.students.find(z=>z.id===id)||s,amount,x.payment.receipt);setTimeout(()=>render('receivePayment'),250);return}catch(e){return alert(e.message)}}const receipt=nextReceiptNumber(),oldPaid=Number(s.paid||0),oldDue=Math.max(0,Number(s.fee||0)-oldPaid);s.paid=oldPaid+amount;s.nextPaymentDate=nextDue;const payment={receipt,receiptNumber:receipt,student:s.id,amount,date,method,reference,note,installment,nextDue,totalCourseFee:Number(s.fee||0),totalPaidAfter:Number(s.paid||0),dueAfter:Math.max(0,Number(s.fee||0)-Number(s.paid||0)),createdAt:new Date().toISOString()};d.payments.push(payment);save();auditChange('Payment received','Student',s.id,'Paid',oldPaid,s.paid,`Receipt ${receipt}; Amount ${money(amount)}`);auditChange('Payment received','Payment',receipt,'Amount','0',money(amount),`Student ${s.id}; Due ${money(oldDue)} → ${money(payment.dueAfter)}`);driveArchiveJson(`Payment-${receipt}.json`,payment,`Students/${s.id}/Payments`);driveArchiveHtml(`Payment-${receipt}.html`,`<h1>MJPTTI Payment Receipt</h1><p>Receipt: ${esc(receipt)}</p><p>Student: ${esc(s.name)} (${esc(s.id)})</p><p>Course: ${esc(s.course||'')}</p><p>Batch: ${esc(s.batch||'')}</p><p>Installment: ${installment}</p><p>Amount: ${money(amount)}</p><p>Date: ${esc(date)}</p><p>Method: ${esc(method)}</p><p>Reference: ${esc(reference)}</p><p>Total Course Fee: ${money(s.fee)}</p><p>Total Paid: ${money(s.paid)}</p><p>Due: ${money(Math.max(0,(s.fee||0)-s.paid))}</p><p>Next Payment Date: ${esc(nextDue)}</p>`,`Students/${s.id}/Payments`);paymentReceipt(receipt);notifyPaymentWhatsApp(s,amount);notifyManagingDirector(s,amount,receipt);setTimeout(()=>render('receivePayment'),250)}
function nextReceiptNumber(){
  const year=new Date().getFullYear();
  const nums=d.payments.map(p=>String(p.receipt||'').match(new RegExp('^REC-'+year+'-(\\d+)$'))).filter(Boolean).map(m=>Number(m[1]));
  const n=(nums.length?Math.max(...nums):0)+1;
  return 'REC-'+year+'-'+String(n).padStart(5,'0');
}

