function accountReportRange(period,fromVal,toVal){
const now=new Date();
const iso=d=>{const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
let start,end;
if(period==='today'){start=end=iso(now)}
else if(period==='yesterday'){const x=new Date(now);x.setDate(x.getDate()-1);start=end=iso(x)}
else if(period==='thisMonth'){start=iso(new Date(now.getFullYear(),now.getMonth(),1));end=iso(new Date(now.getFullYear(),now.getMonth()+1,0))}
else if(period==='lastMonth'){start=iso(new Date(now.getFullYear(),now.getMonth()-1,1));end=iso(new Date(now.getFullYear(),now.getMonth(),0))}
else if(period==='thisYear'){start=iso(new Date(now.getFullYear(),0,1));end=iso(new Date(now.getFullYear(),11,31))}
else if(period==='lastYear'){start=iso(new Date(now.getFullYear()-1,0,1));end=iso(new Date(now.getFullYear()-1,11,31))}
else {start=fromVal||iso(now);end=toVal||iso(now)}
return {start,end};
}
function accountReportHtml(){
const period=val('accountReportPeriod')||'thisMonth';
const r=accountReportRange(period,val('accountReportFrom'),val('accountReportTo'));
const income=d.payments.filter(x=>String(x.date||'')>=r.start&&String(x.date||'')<=r.end).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
const expenses=d.expenses.filter(x=>String(x.date||'')>=r.start&&String(x.date||'')<=r.end).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
const inc=income.reduce((a,x)=>a+Number(x.amount||0),0),ex=expenses.reduce((a,x)=>a+Number(x.amount||0),0),net=inc-ex;
return `<div class="account-report"><div class="report-summary cards">${stat('Income',money(inc))}${stat('Expense',money(ex))}${stat('Net Balance',money(net))}${stat('Transactions',income.length+expenses.length)}</div><div class="grid"><div class="panel"><h3>Income / Student Payments</h3>${income.length?`<div style="overflow:auto"><table class="table"><tr><th>Date</th><th>Receipt</th><th>Student</th><th>Amount</th></tr>${income.map(x=>{const st=d.students.find(s=>s.id===x.student);return `<tr><td>${esc(x.date)}</td><td>${esc(x.receipt||'—')}</td><td>${esc(st?.name||x.student||'—')}<br><small>${esc(x.student||'')}</small></td><td><b>${money(x.amount)}</b></td></tr>`}).join('')}</table></div>`:'<div class="empty">এই সময়সীমায় কোনো আয় পাওয়া যায়নি।</div>'}</div><div class="panel"><h3>Expenses</h3>${expenses.length?`<div style="overflow:auto"><table class="table"><tr><th>Date</th><th>Expense No.</th><th>Purpose / Category</th><th>Amount</th></tr>${expenses.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.no||'—')}</td><td>${esc(x.title||x.purpose||'—')}<br><small>${esc(x.category||'General')} · ${esc(x.method||'Cash')}</small></td><td><b>${money(x.amount)}</b></td></tr>`).join('')}</table></div>`:'<div class="empty">এই সময়সীমায় কোনো ব্যয় পাওয়া যায়নি।</div>'}</div></div></div>`;
}
