function addExpenseItem(){const box=$('expenseItems');if(!box)return;const row=document.createElement('div');row.className='expense-item-row';row.innerHTML=`<input class="exp-item-name" placeholder="Item Name"><input class="exp-item-qty" type="number" min="0" step="1" value="1" placeholder="Qty"><input class="exp-item-price" type="number" min="0" step="0.01" value="0" placeholder="Unit Price"><strong class="exp-item-total">৳0</strong><button class="btn danger" type="button">×</button>`;box.appendChild(row);row.querySelectorAll('input').forEach(i=>i.addEventListener('input',calcExpenseItems));row.querySelector('button').onclick=()=>{row.remove();calcExpenseItems()};calcExpenseItems()}
function calcExpenseItems(){let total=0;document.querySelectorAll('.expense-item-row').forEach(r=>{const q=Number(r.querySelector('.exp-item-qty').value||0),p=Number(r.querySelector('.exp-item-price').value||0),t=q*p;total+=t;r.querySelector('.exp-item-total').textContent=money(t)});if($('expenseGrandTotal'))$('expenseGrandTotal').textContent=money(total);if($('expAmount') && (!Number($('expAmount').value)||$('expAmount').dataset.auto==='1')){$('expAmount').value=total||0;$('expAmount').dataset.auto='1'}}
function syncExpenseAmount(){if($('expAmount'))$('expAmount').dataset.auto='0'}
async function saveDetailedExpense(){const receiver=val('expReceiver').trim(),purpose=val('expPurpose').trim();if(!receiver)return alert('Payment receiver name দিন।');if(!purpose)return alert('Payment purpose দিন।');const items=[...document.querySelectorAll('.expense-item-row')].map(r=>({item:r.querySelector('.exp-item-name').value.trim(),qty:Number(r.querySelector('.exp-item-qty').value||0),unitPrice:Number(r.querySelector('.exp-item-price').value||0),total:Number(r.querySelector('.exp-item-qty').value||0)*Number(r.querySelector('.exp-item-price').value||0)})).filter(x=>x.item);const itemTotal=items.reduce((a,x)=>a+x.total,0);let amount=Number(val('expAmount')||0);if(!amount)amount=itemTotal;if(amount<=0)return alert('Payment amount দিন।');if(itemTotal&&Math.abs(itemTotal-amount)>0.01&&!confirm('Payment Amount এবং Item Total আলাদা। তবুও save করবেন?'))return;try{const r=await financeMutation('expense.create',{expense:{title:purpose,receiver,institution:val('expInstitution'),phone:val('expPhone'),address:val('expAddress'),purpose,description:val('expDescription'),items,amount,date:val('expDate')||today(),category:val('expCategory')||'General',method:val('expMethod')||'Cash',reference:val('expReference'),remarks:val('expRemarks')}});d=r.state;const no=r.record.no;expenseReceipt(no);render('accounts')}catch(e){alert(e.message)}}
function expenseReceipt(no){const x=d.expenses.find(e=>e.no===no);if(!x)return;const items=(x.items||[]).map(i=>`<tr><td>${esc(i.item)}</td><td>${esc(i.qty)}</td><td>${money(i.unitPrice)}</td><td>${money(i.total)}</td></tr>`).join('');const html=officialLetterheadHtml()+`<div class="official-document"><div class="document-title"><span>OFFICIAL FINANCIAL DOCUMENT</span><h1>EXPENSE PAYMENT VOUCHER</h1><div class="receipt-no">${esc(x.no)}</div></div><table class="table receipt-table"><tr><th>Date</th><td>${esc(x.date)}</td><th>Payment Method</th><td>${esc(x.method||'Cash')}</td></tr><tr><th>Receiver Name</th><td>${esc(x.receiver||'—')}</td><th>Institution</th><td>${esc(x.institution||'—')}</td></tr><tr><th>Contact</th><td>${esc(x.phone||'—')}</td><th>Category</th><td>${esc(x.category||'General')}</td></tr><tr><th>Purpose</th><td colspan="3">${esc(x.purpose||x.title||'—')}</td></tr><tr><th>Address</th><td colspan="3">${esc(x.address||'—')}</td></tr></table><p><b>Detailed Description:</b> ${esc(x.description||'—')}</p>${items?`<table class="table receipt-table"><tr><th>Item Name</th><th>Qty</th><th>Unit Price</th><th>Total</th></tr>${items}</table>`:''}<div class="amount-box"><span>TOTAL AMOUNT PAID</span><strong>${money(x.amount)}</strong></div><p><b>Reference:</b> ${esc(x.reference||'—')} &nbsp; <b>Remarks:</b> ${esc(x.remarks||'—')}</p><div class="voucher-signature-footer"><div class="voucher-signature-left"><b>Payment Received By</b><div class="signature-line"></div><small>${esc(x.receiver||'')}<br>Signature</small></div><div class="voucher-signature-right"><b>Authorized By</b><div class="signature-line"></div><small>Authorized Signature</small></div></div><div class="voucher-footer-date">Date: ${esc(x.date)}</div></div>`;openPrintable('Expense Voucher — '+x.no,html,'expense');driveArchiveHtml(`Expense-${x.no}.html`,html,`Accounts/Expenses/${x.date.slice(0,7)}`)}

function driveArchiveExpense(x){driveArchiveJson(`Expense-${x.no}.json`,x,`Accounts/Expenses/${x.date.slice(0,7)}`)}
function driveArchiveHtml(name,html,folder){return driveSend({kind:'document',name,folder,html,meta:{institution:d.settings.name,archivedAt:new Date().toISOString()}})}
