function driveSend(payload){if(cloudMode&&cloudAuthenticated)return api('/api/drive-archive',{method:'POST',body:payload}).catch(e=>({ok:false,error:String(e)}));const cfg=d.settings.drive||{};if(!cfg.endpoint)return Promise.resolve({skipped:true});return fetch(cfg.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,rootFolder:cfg.rootFolder||'MJPTTI Records',institutionalEmail:cfg.institutionalEmail||d.settings.email})}).then(r=>r.json()).catch(e=>({ok:false,error:String(e)}))}

