function studentSearch(q){const base=trainerStudents();const term=String(q||'').trim().toLowerCase();if(!term)return base;return base.filter(s=>Object.values(s).some(v=>{if(v&&typeof v==='object')return Object.values(v).some(z=>String(z??'').toLowerCase().includes(term));return String(v??'').toLowerCase().includes(term)}))}
function filter(q){const term=String(q||'').trim();const rows=term?studentSearch(term):trainerStudents();$('res').innerHTML=table(rows)}
function filterStudents(){
  const batch=$('studentBatchFilter')?.value||'';
  const course=$('studentCourseFilter')?.value||'';
  const term=($('studentTextFilter')?.value||'').trim().toLowerCase();
  let rows=trainerStudents();
  if(batch) rows=rows.filter(s=>String(s.batch||'')===batch);
  if(course) rows=rows=course ? rows.filter(s=>String(s.course||'')===course) : rows;
  if(term) rows=rows.filter(s=>[s.id,s.name,s.namebn,s.phone,s.email,s.batch,s.course].some(v=>String(v||'').toLowerCase().includes(term)));
  const summary=$('studentFilterSummary');
  if(summary){
    const parts=[];
    if(batch) parts.push(`Batch: <b>${esc(batch)}</b>`);
    if(course) parts.push(`Course: <b>${esc(course==='__JLPT_COMBINED__'?'JLPT N5 & N4 Combined':course)}</b>`);
    if(term) parts.push(`Search: <b>${esc(term)}</b>`);
    summary.innerHTML=(parts.length?parts.join(' &nbsp;•&nbsp; '):'Showing all students')+` &nbsp; <b>${rows.length}</b> student${rows.length===1?'':'s'} found`;
  }
  if($('res')) $('res').innerHTML=table(rows);
}
function clearStudentFilters(){
  if($('studentBatchFilter')) $('studentBatchFilter').value='';
  if($('studentCourseFilter')) $('studentCourseFilter').value='';
  if($('studentTextFilter')) $('studentTextFilter').value='';
  filterStudents();
}
function filterPaymentStudents(q){const box=$('paymentSearchResults');if(!box)return;const rows=studentSearch(q).slice(0,20);box.innerHTML=rows.length?rows.map(s=>`<button class="payment-result" onclick="quickPay('${esc(s.id)}')"><b>${esc(s.name)}</b><small>${esc(s.id)} · ${esc(s.phone||'')} · ${esc(s.batch||'')} · ${esc(s.course||'')}</small></button>`).join(''):'<div class="empty">Search result will appear here.</div>'}
