function notifyPaymentWhatsApp(s,amount){if(!s?.phone)return;const due=Math.max(0,(s.fee||0)-(s.paid||0));const msg=`আসসালামু আলাইকুম ${s.name},\n\n${d.settings.name} থেকে আপনার পেমেন্ট আপডেট।\n\nStudent ID: ${s.id}\nআজকের/এই পেমেন্ট: ${money(amount)}\nমোট পেমেন্ট: ${money(s.paid)}\nমোট কোর্স ফি: ${money(s.fee)}\nবাকি: ${money(due)}\nপরবর্তী পেমেন্টের তারিখ: ${s.nextPaymentDate||'নির্ধারিত নয়'}\n\nধন্যবাদ।\n${d.settings.name}`;openWhatsAppWindow(s.phone,msg,'MJPTTI_STUDENT_WHATSAPP')}
function notifyManagingDirector(s,amount,receipt){const msg=`MJPTTI INSTITUTIONAL PAYMENT NOTIFICATION\n\nStudent: ${s.name}\nStudent ID: ${s.id}\nCourse: ${s.course||''}\nBatch: ${s.batch||''}\nPayment Received: ${money(amount)}\nTotal Paid: ${money(s.paid)}\nDue: ${money(Math.max(0,(s.fee||0)-(s.paid||0)))}\nNext Payment: ${s.nextPaymentDate||'—'}\nReceipt: ${receipt}\nDate: ${today()}\n\nMeherun JP Technical Training Institute`;
openWhatsAppWindow('01351745050',msg,'MJPTTI_MD_WHATSAPP')}
function openWhatsAppWindow(raw,msg,target='MJPTTI_WHATSAPP'){const phone=waPhone(raw);if(!phone)return;const url=`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`;const key=target==='MJPTTI_MD_WHATSAPP'?'__mjpttiMDWhatsAppWindow':'__mjpttiStudentWhatsAppWindow';let w=window[key];if(!w||w.closed)w=window[key]=window.open(url,target);else w.location.href=url;try{w.focus()}catch(e){}}
