function welcomeWhatsApp(id){const s=d.students.find(x=>x.id===id);if(!s||!s.phone)return alert('Student phone number not found.');const phone=waPhone(s.phone);if(!phone)return alert('Valid WhatsApp number not found.');const cred=window.__mjpttiLastCredentials?.id===id?window.__mjpttiLastCredentials:null;const passwordLine=cred?.password?`Password: ${cred.password}`:'Password: Please use the credential issued by MJPTTI.';const msg=`Assalamu Alaikum ${s.name},\n\n🎓 Welcome to ${d.settings.name}!\nYour admission has been successfully confirmed.\n\nStudent ID: ${s.id}\nCourse: ${s.course}\nBatch: ${s.batch}\nUsername: ${cred?.username||s.username||s.id}\n${passwordLine}\n\nPlease keep your admission information safe and use your username and password to access the Student Portal.\n\nWebsite: ${websiteUrl()}\n\nThank you,\n${d.settings.name}`;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'MJPTTI_WHATSAPP')}
