function whatsappReminder(id){const s=d.students.find(x=>x.id===id);if(!s||!s.phone)return alert('Student phone number not found.');const due=Math.max(0,s.fee-s.paid);if(due<=0)return alert('This student has no outstanding due.');const history=d.payments.filter(p=>p.student===s.id).sort((a,b)=>String(b.date).localeCompare(String(a.date)));const last=history[0];const msg=`আসসালামু আলাইকুম ${s.name},\n\n${d.settings.name} থেকে Payment Due Reminder.\n\nStudent ID: ${s.id}\nCourse: ${s.course||'—'}\nBatch: ${s.batch||'—'}\nTotal Course Fee: ${money(s.fee)}\nTotal Paid: ${money(s.paid)}\nOutstanding Due: ${money(due)}\nNext Payment Date: ${s.nextPaymentDate||'Not set'}${last?`\nLast Payment: ${money(last.amount)} on ${last.date}`:''}\n\nঅনুগ্রহ করে নির্ধারিত সময়ের মধ্যে বকেয়া পরিশোধ করুন।\n\nধন্যবাদ,\n${d.settings.name}`;const phone=waPhone(s.phone);window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'MJPTTI_WHATSAPP')}

async function syncVerificationDatabase(){
  const key=($('verificationSyncKey')?.value||'').trim();
  const out=$('verificationSyncStatus');
  if(!key)return alert('Verification Sync Key দিন।');
  if(!d.students.length)return alert('কোনো student record নেই।');
  if(out)out.textContent='Syncing…';
  const students=d.students.map(s=>({id:s.id,name:s.name,namebn:s.namebn||'',course:s.course||'',batch:s.batch||'',dob:s.dob||'',phone:s.phone||'',photo:s.photo||'',status:s.status||'Active'}));
  try{
    const r=await fetch('/api/student-sync',{method:'POST',headers:{'Content-Type':'application/json','X-MJPTTI-SYNC-KEY':key},body:JSON.stringify({students})});
    const x=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(x.error||'Verification sync failed');
    if(out)out.textContent=`✓ ${x.synced||students.length} student(s) synced successfully.`;
  }catch(e){if(out)out.textContent='';alert(String(e.message||e));}
}

function makeBackupPayload(){return {format:'MJPTTI_FULL_BACKUP',version:2,createdAt:new Date().toISOString(),data:JSON.parse(JSON.stringify(d))};}
function formatBackupSize(bytes){if(!bytes)return '—';if(bytes<1024)return bytes+' B';if(bytes<1048576)return (bytes/1024).toFixed(1)+' KB';return (bytes/1048576).toFixed(2)+' MB';}
function saveBackupMeta(payload){const raw=JSON.stringify(payload);localStorage.setItem('mjptti_last_backup',JSON.stringify({createdAt:payload.createdAt,size:new Blob([raw]).size}));}
function updateBackupMeta(){try{const m=JSON.parse(localStorage.getItem('mjptti_last_backup')||'null');const date=$('lastBackupDate'),size=$('lastBackupSize'),state=$('backupReminderState');if(date)date.textContent=m?.createdAt?new Date(m.createdAt).toLocaleString():'Not available';if(size)size.textContent=m?.size?formatBackupSize(m.size):'Not available';const cfg=JSON.parse(localStorage.getItem('mjptti_backup_reminder')||'null')||{enabled:true,days:7};const due=m?.createdAt && (Date.now()-new Date(m.createdAt).getTime()>cfg.days*86400000);if(state)state.textContent=cfg.enabled?(due?'⚠ Backup due':'Every '+cfg.days+' days'):'Disabled';if($('backupReminderEnabled'))$('backupReminderEnabled').checked=cfg.enabled;if($('backupReminderDays'))$('backupReminderDays').value=String(cfg.days);if(cfg.enabled&&due&&!sessionStorage.getItem('mjptti_backup_reminder_shown')){sessionStorage.setItem('mjptti_backup_reminder_shown','1');setTimeout(()=>alert('Backup reminder: আপনার সর্বশেষ backup নির্ধারিত সময়ের চেয়ে পুরোনো। নিরাপত্তার জন্য এখন একটি Full Backup নিন।'),500)}}catch(e){}}
function saveBackupReminderSettings(){const enabled=!!$('backupReminderEnabled')?.checked,days=Number($('backupReminderDays')?.value||7);localStorage.setItem('mjptti_backup_reminder',JSON.stringify({enabled,days}));updateBackupMeta();}
async function downloadFullBackup(silent=false){try{if(cloudMode&&cloudAuthenticated){const r=await fetch('/api/backup-export',{credentials:'include'});const blob=await r.blob();if(!r.ok){let msg='Cloud backup failed';try{msg=(await blob.text())||msg}catch{}throw new Error(msg)}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`MJPTTI_Full_D1_Backup_${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);const st=$('backupStatus');if(st)st.textContent='Full D1 backup downloaded successfully · '+formatBackupSize(blob.size);if(!silent)audit('Backup Created','Full D1 backup downloaded; size '+formatBackupSize(blob.size));return true;}const payload=makeBackupPayload();const raw=JSON.stringify(payload,null,2);const blob=new Blob([raw],{type:'application/json'});saveBackupMeta(payload);updateBackupMeta();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`MJPTTI_Full_Backup_${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);const st=$('backupStatus');if(st)st.textContent='Full backup created successfully · '+formatBackupSize(blob.size)+' · '+new Date(payload.createdAt).toLocaleString();if(!silent)audit('Backup Created','Full backup downloaded; size '+formatBackupSize(blob.size));return true;}catch(e){if(!silent)alert('Backup তৈরি করা যায়নি।');return false;}}
function validateBackupPayload(payload){const x=payload?.data;const required=['students','staff','payments','expenses','officeAdvances','staffSalaries','salarySheets','attendance','staffAttendance','exams','examList','certificates','courses','batches','teachers','notices','settings'];if(payload?.format!=='MJPTTI_FULL_BACKUP'||!x||typeof x!=='object')return 'Invalid backup format';if(!required.every(k=>k in x))return 'Backup is incomplete: required data sections are missing';if(!Array.isArray(x.students)||!Array.isArray(x.staff)||!Array.isArray(x.payments)||!Array.isArray(x.attendance)||!x.settings)return 'Backup data types are invalid';return null;}
function duplicateBackupWarning(x){const currentIds=new Set((d.students||[]).map(s=>String(s.id||'')));const incomingIds=(x.students||[]).map(s=>String(s.id||'')).filter(Boolean);const duplicates=incomingIds.filter(id=>currentIds.has(id));return {count:duplicates.length,sample:duplicates.slice(0,8)};}
function restoreFullBackup(input){if(cloudMode&&cloudAuthenticated){if(input)input.value='';return alert('Cloud mode-এ browser backup restore নিরাপদ নয়। আগে Full D1 Backup নিন এবং D1-level recovery ব্যবহার করুন।');}const file=input?.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const payload=JSON.parse(reader.result);const err=validateBackupPayload(payload);if(err)throw new Error(err);const x=payload.data;const dup=duplicateBackupWarning(x);let warning='';if(dup.count)warning=`\n\n⚠ Duplicate warning: ${dup.count} Student ID(s) already exist in the current portal.`;const backupRaw=JSON.stringify(makeBackupPayload(),null,2);const safetyBlob=new Blob([backupRaw],{type:'application/json'});const safetyName=`MJPTTI_Pre_Restore_Backup_${today()}.json`;const safetyUrl=URL.createObjectURL(safetyBlob);const safetyA=document.createElement('a');safetyA.href=safetyUrl;safetyA.download=safetyName;document.body.appendChild(safetyA);safetyA.click();safetyA.remove();setTimeout(()=>URL.revokeObjectURL(safetyUrl),1000);localStorage.setItem('mjptti_last_backup',JSON.stringify({createdAt:new Date().toISOString(),size:safetyBlob.size,type:'pre-restore'}));const ok=confirm('Import validation passed.\n\nBefore restore, an automatic safety backup has been created and downloaded.\n\nRestore will replace the current portal data with this backup.'+warning+'\n\nContinue?');if(!ok){input.value='';return}d=x;normalize();save();localStorage.removeItem('mjptti_session');alert('Backup restored successfully. Portal এখন reload হবে।');location.reload();}catch(e){input.value='';alert('Restore blocked.\n\n'+(e.message||'Invalid MJPTTI backup file.'));}};reader.readAsText(file);}

function applyInstitutionBranding(){
  const name=d.settings?.institutionName||d.settings?.name||'Meherun JP Technical Training Institute';
  const logo=d.settings?.institutionLogo||'';
  document.querySelectorAll('img[src*="mjptti-logo.png"]').forEach(img=>{if(logo)img.src=logo;});
  document.querySelectorAll('.brand b').forEach(el=>{if(el.textContent.includes('MJPTTI')||el.dataset.brandName==='institution')el.textContent=name;});
  document.querySelectorAll('.loginbox small,.public-top .brandline b').forEach(el=>el.textContent=name.toUpperCase());
  document.querySelectorAll('aside footer').forEach(el=>el.textContent=d.settings?.motto||'Empowering Skills, Building Future');
  document.querySelectorAll('[data-brand="institution-name"]').forEach(el=>el.textContent=name);
  document.querySelectorAll('[data-brand="institution-address"]').forEach(el=>el.textContent=d.settings?.institutionAddress||d.settings?.bdAddress||'');
  document.querySelectorAll('[data-brand="institution-phone"]').forEach(el=>el.textContent=d.settings?.institutionPhone||d.settings?.phone||'');
  document.querySelectorAll('[data-brand="institution-email"]').forEach(el=>el.textContent=d.settings?.institutionEmail||d.settings?.email||'');
}
