async function saveAdminCredentials(){const u=String(val('adminUsername')||'').trim(),p=String(val('adminPassword')||''),p2=String(val('adminPassword2')||'');if(!u)return alert('Admin username দিন।');if(p.length<8)return alert('Password কমপক্ষে 8 characters হতে হবে।');if(p!==p2)return alert('Password দুটো মিলছে না।');try{if(cloudMode){const out=await api('/api/admin-credentials',{method:'POST',body:{username:u,password:p,version:cloudVersion}});cloudVersion=Number(out.version||cloudVersion+1)}d.settings.adminUsername=u;delete d.settings.adminPassword;if(!cloudMode)save();$('adminPassword').value='';$('adminPassword2').value='';$('adminCredStatus').textContent='Admin credentials updated successfully.';}catch(e){alert(e.message)}}
